static int CalculateDamage(int baseDamage, int bonus)
{
    return baseDamage + bonus;
}

int damage = CalculateDamage(20, 5);
Console.WriteLine("Урон: " + damage);

static int Heal(int hp, int healAmount)
{
    return hp + healAmount;
}

int playerHealth = 60;
playerHealth = Heal(playerHealth, 25);

Console.WriteLine("HP после лечения: " + playerHealth);

