class Enemy
{
    public int Health = 50;
}

class Player
{
    public int Damage = 20;

    public void Attack(Enemy enemy)
    {
        enemy.Health -= Damage;
    }
}

Player hero = new Player();
Enemy goblin = new Enemy();

hero.Attack(goblin);

Console.WriteLine("HP врага: " + goblin.Health);
